/** Gold pill button with the white circular arrow (".mccaa-button-gold" on the original). */
function GoldButton({
  href,
  children,
  external,
  className,
  paddingLeft = "pl-[60px]",
  gap = "gap-[37px]",
}: {
  href: string;
  children: React.ReactNode;
  external?: boolean;
  className?: string;
  paddingLeft?: string;
  gap?: string;
}) {
  const classes = cn(
    "group inline-flex items-center rounded-pill bg-brand-gold py-[5px] pr-[7px] text-[20px] font-normal leading-none text-white transition-colors duration-300 hover:bg-brand-gold-dark",
    paddingLeft,
    gap,
    className
  );
  const icon = (
    <span className="flex h-[33.5px] w-[33.5px] items-center justify-center rounded-full bg-white text-black">
      <ArrowIcon className="h-[13.5px] w-[13.5px] transition-transform duration-300 group-hover:rotate-45" />
    </span>
  );
  if (external) {
    return (
      <a href={href} target="_blank" rel="noopener noreferrer" className={classes}>
        <span>{children}</span>
        {icon}
      </a>
    );
  }
  return (
    <Link href={href} className={classes}>
      <span>{children}</span>
      {icon}
    </Link>
  );
}

function SectionLabel({ children }: { children: React.ReactNode }) {
  return <p className="text-[16px] font-medium uppercase leading-none text-brand-teal">{children}</p>;
}

